#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using ull = unsigned long long;

const int MAX_N = 250005, MAX_M = 1 << 17, MAX_D = 18;

int P;
int modPow(int base, int exp) {
    int res = 1;
    while (exp) {
        if (exp & 1) res = (ll)res * base % P;
        base = (ll)base * base % P;
        exp >>= 1;
    }
    return res;
}

int L, K, fac[MAX_N], n, m, bits[20], ifac[MAX_N], popcount[MAX_N];
ll suma[MAX_D][MAX_M], sumc[MAX_D][MAX_M];
ull dp[MAX_D][MAX_M], tmp[MAX_D][MAX_M];

int main() {
    scanf("%d%d%d", &L, &K, &P);
    fac[0] = 1;
    for (int i = 1; i <= L; ++i) {
        fac[i] = (ll)fac[i - 1] * i % P;
        popcount[i] = popcount[i >> 1] + (i & 1);
    }
    ll total = modPow(K, L);
    if (L & 1) {
        printf("%lld\n", total);
        return 0;
    }

    ifac[L] = modPow(fac[L], P - 2);
    for (int i = L; i >= 1; --i) ifac[i - 1] = (ll)ifac[i] * i % P;
    for (int i = 1; (1 << i) <= L; ++i) if (L >> i & 1) bits[n++] = 1 << i;

    m = 1 << n;
    for (int i = 0; i < m; ++i) {
        int s = 0;
        for (int j = 0; j < n; ++j) if (i >> j & 1) s += bits[j];
        suma[popcount[i]][i] = ifac[s];
    }

    for (int t = 0; t <= n; ++t) {
        ll* a = suma[t];
        for (int len = m; len >= 2; len >>= 1)
            for (int j = 0, step = len >> 1; j < m; j += len)
                for (int k = 0; k < step; ++k) a[j + k + step] += a[j + k];
        for (int j = 0; j < m; ++j) a[j] %= P;
    }

    for (int t = 0; t <= n; ++t) memcpy(dp[t], suma[t], m << 3);
    int revK = 0, cnt = 0;
    for (int temp = K; temp; temp >>= 1) {
        revK = (revK << 1) | (temp & 1);
        ++cnt;
    }
    --cnt; revK >>= 1;
    for (; cnt; --cnt, revK >>= 1) {
        for (int t = 0; t <= n; ++t) memset(tmp[t], 0, m << 3);
        for (int a = 0; a <= n; ++a)
            for (int b = 0; a + b <= n; ++b) {
                ull* f = tmp[a + b];
                const ull* g = dp[a];
                const ull* h = dp[b];
                for (int j = 0; j < m; ++j) f[j] += g[j] * h[j];
            }
        for (int t = 0; t <= n; ++t)
            for (int j = 0; j < m; ++j) dp[t][j] = tmp[t][j] % P;

        if (revK & 1) {
            for (int t = 0; t <= n; ++t) memset(tmp[t], 0, m << 3);
            for (int a = 0; a <= n; ++a)
                for (int b = 0; a + b <= n; ++b) {
                    ull* f = tmp[a + b];
                    const ull* g = dp[a];
                    const ll* h = suma[b];
                    for (int j = 0; j < m; ++j) f[j] += g[j] * h[j];
                }
            for (int t = 0; t <= n; ++t)
                for (int j = 0; j < m; ++j) dp[t][j] = tmp[t][j] % P;
        }
    }

    for (int t = 0; t <= n; ++t) memcpy(sumc[t], dp[t], m << 3);
    for (int t = 0; t <= n; ++t) {
        ll* a = sumc[t];
        for (int len = 2; len <= m; len <<= 1)
            for (int j = 0, step = len >> 1; j < m; j += len)
                for (int k = 0; k < step; ++k) a[j + k + step] -= a[j + k];
        for (int j = 0; j < m; ++j) a[j] = (a[j] % P + P) % P;
    }

    ll ans = (total - sumc[n][(1 << n) - 1] * fac[L] % P + P) % P;
    printf("%lld\n", ans);
    return 0;
}
